271	        // that finds room reads no clock, and each later check is one reading and a compare or two.
272	        let mut ends: Option<(u64, u64)> = None;
273	        self.send(
274	            |_| {
275	                if spin_time == Ticks::FOREVER {
276	                    core::hint::spin_loop();
277	                    return true;
278	                }
279	                let now = now_ticks();
280	                let (spin_end, sleep_end) = *ends.get_or_insert_with(|| {
281	                    let spin_end = now.saturating_add(spin_time.0);
282	                    (spin_end, spin_end.saturating_add(sleep_time.0))
283	                });
284	                if now < spin_end {
285	                    core::hint::spin_loop();
286	                    return true;
287	                }
288	                let deadline = if sleep_time == Ticks::FOREVER {
289	                    None
290	                } else if now >= sleep_end {
291	                    return false;
292	                } else {
293	                    Some(Deadline::at(sleep_end))
294	                };
295	                if W::WAKES {
296	                    self.sleep_full(deadline);
297	                } else {
298	                    core::hint::spin_loop();
299	                }
300	                true
301	            },
302	            write_msg,
